{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/story-tabs.json
    A story in steps (years or slides). Axes: layout (years: a row of year tabs over the panel of the active year with its badge, step, title, text and tag; carousel: the heading beside a picture with previous and next arrows and one dot per step), tone. Choosing a step emits `select`.
    Props (p): id, title, lead, badge, steps, active, labels, layout, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_badge = ($p['badge'] ?? '')}
{var $v_steps = ($p['steps'] ?? null)}
{var $v_active = ($p['active'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'years')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{if ui_t(ui_eq($v_layout, 'years'))}
  {capture $c_5}
    {capture $c_4}
      {foreach ui_l($v_steps) as $v_s}
        {capture $c_3}
          {capture $c_1}
            {=ui_text(ui_get($v_s, ['date']))}
          {/capture}
          {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'text-sm font-semibold'], 'children' => $c_1])|noescape}
          {capture $c_2}
            {=ui_text(ui_get($v_s, ['tag']))}
          {/capture}
          {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'text-xs'], 'children' => $c_2])|noescape}
        {/capture}
        {=ui_include('ui/button/button.latte', ['p' => ['Variant' => ui_s((ui_t(ui_eq(ui_get($v_s, ['id']), $v_active)) ? 'default' : 'outline')), 'Size' => 'lg', 'Type' => 'button', 'Class' => 'h-auto flex-col items-start gap-0 py-2 text-start', 'Attrs' => ui_attrs(['data-testid', 'story-tab', 'data-active', (ui_t(ui_eq(ui_get($v_s, ['id']), $v_active)) ? 'true' : 'false')])], 'children' => $c_3])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-2 gap-2 sm:grid-cols-4', 'Attrs' => ui_attrs(['data-testid', 'story-tabs'])], 'children' => $c_4])|noescape}
    {foreach ui_l($v_steps) as $v_s}
      {var $v_i = $iterator->counter0}
      {if ui_t(ui_eq(ui_get($v_s, ['id']), $v_active))}
        {=ui_include('blocks/story-panel.latte', ['p' => ['s' => $v_s, 'index' => $v_i, 'total' => ui_len($v_steps), 'labels' => $v_labels]])|noescape}
      {/if}
    {/foreach}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_5])|noescape}
{else}
  {capture $f_6}
    {capture $c_10}
      {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '4/3']])|noescape}
      {capture $c_9}
        {capture $c_7}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'chevron-left', 'Size' => 16]])|noescape}
        {/capture}
        {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm', 'Layout' => 'icon', 'Type' => 'button', 'AriaLabel' => ui_s(ui_get($v_labels, ['previous'])), 'Attrs' => ui_attrs(['data-testid', 'story-arrow'])], 'children' => $c_7])|noescape}
        {=ui_include('blocks/story-dots.latte', ['p' => ['steps' => $v_steps, 'active' => $v_active]])|noescape}
        {capture $c_8}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'chevron-right', 'Size' => 16]])|noescape}
        {/capture}
        {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm', 'Layout' => 'icon', 'Type' => 'button', 'AriaLabel' => ui_s(ui_get($v_labels, ['next'])), 'Attrs' => ui_attrs(['data-testid', 'story-arrow'])], 'children' => $c_8])|noescape}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Justify' => 'between'], 'children' => $c_9])|noescape}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch'], 'children' => $c_10])|noescape}
  {/capture}
  {=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true], 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_6]])|noescape}
{/if}
